    function titleSkyArt() {
        const hour = new Date().getHours();

        const day = [
            '                 \\  |  /',
            '               --  O  --',
            '                 /  |  \\',
            '       .--.                    .---.',
            '    .-(    ).               .-(     ).',
            '   (___.__)__)             (___._____)',
            '',
            '                 /\\',
            '           _/\\__/  \\__/\\_',
            '       ___/              \\___',
            '   ___/                      \\____',
            '~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~',
            ' ~~~  ~~~~~  ~~~  ~~~~~  ~~~  ~~~~~~',
            '       |\\',
            '       | \\____',
            '       |______\\       FERRY'
        ];

        const dusk = [
            '                         .----.',
            '       .--.             /      \\',
            '    .-(    ).           \\______/',
            '   (___.__)__)',
            '',
            '                 /\\',
            '           _/\\__/  \\__/\\_',
            '       ___/              \\___',
            '   ___/                      \\____',
            '~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~',
            ' ~~~  ~~~~~  ~~~  ~~~~~  ~~~  ~~~~~~',
            '       |\\',
            '       | \\____',
            '       |______\\       FERRY'
        ];

        const night = [
            '      *          .             *',
            '             *          _..._',
            '                       .     .',
            '       .               (     )       *',
            '                        `---\\',
            '                 /\\',
            '           _/\\__/  \\__/\\_',
            '       ___/              \\___',
            '   ___/                      \\____',
            '~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~',
            ' ~~~  ~~~~~  ~~~  ~~~~~  ~~~  ~~~~~~',
            '       |\\',
            '       | \\____',
            '       |______\\       FERRY'
        ];

        if (hour >= 5 && hour < 17) return day.join('\\n');
        if (hour >= 17 && hour < 20) return dusk.join('\\n');
        return night.join('\\n');
    }

    function formatSaveTime(timestamp) {
        if (!timestamp) return 'No timestamp';

        try {
            return new Date(timestamp).toLocaleString([], {
                dateStyle: 'medium',
                timeStyle: 'short'
            });
        }
        catch (_) {
            return new Date(timestamp).toLocaleString();
        }
    }

